DROP TABLE IF EXISTS "Usuarios";
DROP TABLE IF EXISTS "Socios";
DROP TABLE IF EXISTS "Planes";

CREATE TABLE "Planes" (
    "PlanId"        INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_Planes" PRIMARY KEY,
    "Nombre"        VARCHAR(50)   NOT NULL CONSTRAINT "UQ_Planes_Nombre" UNIQUE,
    "Precio"        NUMERIC(8,2)  NOT NULL CONSTRAINT "CK_Planes_Precio" CHECK ("Precio" > 0),
    "DuracionMeses" INT           NOT NULL CONSTRAINT "CK_Planes_Duracion" CHECK ("DuracionMeses" BETWEEN 1 AND 24),
    "Activo"        BOOLEAN       NOT NULL DEFAULT TRUE
);

CREATE TABLE "Socios" (
    "SocioId"          INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_Socios" PRIMARY KEY,
    "Nombres"          VARCHAR(100) NOT NULL,
    "Dni"              CHAR(8)      NOT NULL CONSTRAINT "UQ_Socios_Dni" UNIQUE,
    "Email"            VARCHAR(100) NULL,
    "Edad"             INT          NOT NULL CONSTRAINT "CK_Socios_Edad" CHECK ("Edad" BETWEEN 14 AND 90),
    "FechaInscripcion" DATE         NOT NULL DEFAULT CURRENT_DATE,
    "PlanId"           INT          NOT NULL CONSTRAINT "FK_Socios_Planes" REFERENCES "Planes"("PlanId")
);
CREATE INDEX "IX_Socios_PlanId" ON "Socios"("PlanId");

CREATE TABLE "Usuarios" (
    "UsuarioId" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_Usuarios" PRIMARY KEY,
    "Correo"    VARCHAR(100) NOT NULL CONSTRAINT "UQ_Usuarios_Correo" UNIQUE,
    "ClaveHash" VARCHAR(200) NOT NULL,
    "Rol"       VARCHAR(50)  NOT NULL
);

